const lines = cart.lines
  .filter((l) => l.quantity > 0)
  .map((l) => ({ sku: l.sku, quantity: Math.min(l.quantity, 99), shownPrice: l.shownPrice }))
if (!lines.length) throw new Error('nothing to order')
const total = lines.reduce((sum, l) => sum + l.quantity * l.shownPrice, 0)
// One key per cart: a retried request is the same order, never a second one.
const idempotencyKey = `cart-${cart.id}-${lines.map((l) => `${l.sku}x${l.quantity}`).join('.')}`
const req: OrderRequest = {
  cartId: cart.id,
  customer,
  lines,
  shipping: { ...cart.shipping, country: cart.shipping.country.toUpperCase() },
  total,
  idempotencyKey,
}
if (cart.coupon) req.coupon = cart.coupon.trim().toUpperCase()
// A gift note travels as text; the server never renders it as HTML.
if (giftNote) {
  const note = giftNote.trim().slice(0, 500)
  if (note) req.giftNote = note
}
